def by_length(arr):
    if not arr:
        return []

    filtered = [x for x in arr if 1 <= x <= 9]
    filtered.sort()
    reversed_names = [name_from_digit(x) for x in reversed(filtered)]
    return reversed_names

def name_from_digit(d):
    names = {
        1: "One",
        2: "Two",
        3: "Three",
        4: "Four",
        5: "Five",
        6: "Six",
        7: "Seven",
        8: "Eight",
        9: "Nine"
    }
    return names.get(d, "")
